class Solution {
public:
    int binaryGap(long long n) {
        int last = -1, ans = 0, pos = 0;
        while (n > 0) {
            if (n & 1LL) {
                if (last != -1) ans = max(ans, pos - last);
                last = pos;
            }
            n >>= 1;
            ++pos;
        }
        return ans;
    }
};

